entries.content:
@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@300;400&display=swap');
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    scroll-behavior: smooth;
    font-family: 'Montserrat', sans-serif;
    color: white;
}

:root {
    --violet: #d33bdf;
}

body {
    color: black;
    font-size: 14px;
}

header {
    background: linear-gradient(#13181d, #20212e, #341b47)
}

nav {
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;

}

nav h1 {
    color: var(--violet);
    margin-left: 20px;
    cursor: pointer;
    transition: all ease 0.4s;
}

nav h1:hover {
    transform: scale(1.1, 1.1);
}

nav a {
    text-decoration: none;
    margin-right: 20px;
}

nav a::after {
    content: "";
    display: block;
    width: 0px;
    background: var(--violet);
    color: white;
    height: 1px;
    transition: width 0.5s;
}

nav a:hover::after {
    width: 100%;
}

.buttonachat {
    padding: 5px 15px;
    border: 1px solid var(--violet);
    color: var(--violet);
    background-color: transparent;
    border-radius: 5px;
    cursor: pointer;
    transition: all 0.5s;
}

.buttonachat:hover {
    background-color: var(--violet);
    color: white;
}

#right {
    display: flex;
    justify-content: center;
    align-items: center;
    margin-right: 55px;
}

.hero-left {}

.hero-left h2 {
    font-size: 60px;
    margin-bottom: 30px;
    margin-left: 15px;
}

.hero-left p {
    font-size: 20px;
    margin-bottom: 30px;
    margin-left: 15px;
}

.hero button {
    margin: 0px 0px 10px 15px;
}

.hero {
    margin-top: 50px;
    display: flex;
    justify-content: space-between;
}

.hero-images {
    background-color: rgb(51, 49, 77);
    width: 150px;
    height: 150px;
    border-radius: 15px;
    margin-left: 15px;
    margin-top: 10px;
    transition: all ease 0.4s
}

.hero-images:hover {
    opacity: 0.7;
    cursor: pointer;
    transform: translateY(10px) scale(1.1, 1.1) rotate(45deg);
}

.hero-right img {
    cursor: pointer;
    transition: all ease 0.4s
}

.hero-right img:hover {
    transform: scale(1.1, 1.1) rotate(15deg);

}
.presentation-left{
    margin-left: 70px;
}
.presentation-left h3{
    font-size: 40px;
    margin-bottom: 15px;

}
#p1{ 
    margin-top: 120px;
   color:var(--violet);
   margin-bottom:25px;
}
#p2{
   margin-bottom:25px;
   width: 60%;
}
.presentation-right {
    margin-right: 100px;
}
#hero2{
    background-color: #13181d;;
}

@media screen and (max-width:640px) {
    nav a {
        display: none;
    }

    .hero {
        display: flex;
        flex-direction: column;

        h2 {
            font-size: 20px;
            text-align: center;
        }

        p {
            font-size: 14px;
            text-align: center;
        }

        button {
            margin-left: 40px;
            margin: auto;
            font-size: 14px;
            text-align: center;
        }
    }
}
